typedef struct OrbitASTVariantNode { int tag; void* data; } OrbitASTVariantNode;
static inline OrbitASTVariantNode* orbit_create_variant(OrbitArena* a, int tag, void* data) {
    OrbitASTVariantNode* n = (OrbitASTVariantNode*)orbit_alloc(a, sizeof(OrbitASTVariantNode));
    n->tag = tag; n->data = data; return n;
}
