static inline orbit_bool orbit_val_eq(void* a, void* b) {
    if (a == b) return true;
    if (!a || !b) return false;
    if ((uintptr_t)a < 65536 || (uintptr_t)b < 65536) return false;
    return strcmp((const char*)a, (const char*)b) == 0;
}

